//! A synthetic OOXML I/O contract for positive table cell spacing.
//! The fixture is generated by this crate; only tblCellSpacing is injected.

use std::collections::BTreeMap;
use std::io::{Cursor, Read, Write};
use std::sync::Arc;

use quick_xml::XmlVersion;
use quick_xml::events::Event;
use quick_xml::reader::Reader;
use wordcraft_doc::table::{Cell, Table};
use wordcraft_doc::{Block, Document};

const MAIN: &str = "word/document.xml";
const SPACING: &str = r#"<w:tblCellSpacing w:w="15" w:type="dxa"/>"#;

fn unzip(bytes: &[u8]) -> BTreeMap<String, Vec<u8>> {
    let mut archive = zip::ZipArchive::new(Cursor::new(bytes)).unwrap();
    let mut parts = BTreeMap::new();
    for index in 0..archive.len() {
        let mut part = archive.by_index(index).unwrap();
        let name = part.name().to_string();
        let mut payload = Vec::new();
        part.read_to_end(&mut payload).unwrap();
        assert!(parts.insert(name, payload).is_none(), "no duplicate ZIP parts");
    }
    parts
}

fn zip(parts: &BTreeMap<String, Vec<u8>>) -> Vec<u8> {
    let mut archive = zip::ZipWriter::new(Cursor::new(Vec::new()));
    for (name, payload) in parts {
        archive.start_file(name, zip::write::SimpleFileOptions::default()).unwrap();
        archive.write_all(payload).unwrap();
    }
    archive.finish().unwrap().into_inner()
}

fn table_cell_spacing(xml: &[u8]) -> Vec<BTreeMap<String, String>> {
    let mut reader = Reader::from_reader(xml);
    let mut buffer = Vec::new();
    let mut in_table_properties = false;
    let mut spacing = Vec::new();
    loop {
        buffer.clear();
        match reader.read_event_into(&mut buffer).unwrap() {
            Event::Start(element) | Event::Empty(element) => {
                let name = String::from_utf8_lossy(element.local_name().as_ref()).into_owned();
                if name == "tblPr" {
                    in_table_properties = true;
                } else if in_table_properties && name == "tblCellSpacing" {
                    spacing.push(
                        element
                            .attributes()
                            .map(|attribute| {
                                let attribute = attribute.unwrap();
                                let name = String::from_utf8_lossy(attribute.key.as_ref()).into_owned();
                                let value = attribute.normalized_value(XmlVersion::Explicit1_0).unwrap().into_owned();
                                (name, value)
                            })
                            .collect(),
                    );
                }
            }
            Event::End(element) if element.local_name().as_ref() == b"tblPr" => in_table_properties = false,
            Event::Eof => return spacing,
            _ => {}
        }
    }
}

#[test]
fn table_cell_spacing_survives_docx_read_and_reexport_in_twentieths_of_a_point() {
    let mut document = Document::from_text("Synthetic table spacing fixture.");
    let mut table = Table::new(1, 2, 144.0);
    table.rows[0].cells = vec![Cell::with_text("Synthetic left cell"), Cell::with_text("Synthetic right cell")];
    document.body.push(Arc::new(Block::Table(table)));
    let original = unzip(&wordcraft_docx::write(&document).unwrap());
    let original_xml = String::from_utf8(original[MAIN].clone()).unwrap();
    assert!(table_cell_spacing(original_xml.as_bytes()).is_empty());
    assert_eq!(original_xml.matches("<w:tblPr>").count(), 1, "one table property set in the Rust-generated fixture");

    let modified_xml = original_xml.replacen("<w:tblPr>", &format!("<w:tblPr>{SPACING}"), 1);
    let mut injected = original.clone();
    injected.insert(MAIN.into(), modified_xml.into_bytes());
    let fixture = zip(&injected);
    let actual_fixture = unzip(&fixture);
    assert!(actual_fixture.keys().eq(original.keys()), "the injection adds no package parts");
    let changed: Vec<_> =
        original.iter().filter(|(name, payload)| actual_fixture.get(*name) != Some(*payload)).map(|(name, _)| name.as_str()).collect();
    assert_eq!(changed, [MAIN], "all other uncompressed package payloads stay byte-identical");
    let actual_xml = String::from_utf8(actual_fixture[MAIN].clone()).unwrap();
    assert_eq!(actual_xml.matches(SPACING).count(), 1);
    assert_eq!(actual_xml.replacen(SPACING, "", 1), original_xml, "the sole document.xml intervention is this element");
    let expected = vec![BTreeMap::from([("w:w".into(), "15".into()), ("w:type".into(), "dxa".into())])];
    assert_eq!(table_cell_spacing(actual_xml.as_bytes()), expected, "the positive spacing is present before the reader");

    let reopened = wordcraft_docx::read(&fixture).unwrap();
    let reexported = unzip(&wordcraft_docx::write(&reopened).unwrap());
    assert_eq!(
        table_cell_spacing(&reexported[MAIN]),
        expected,
        "15 twentieths of a point (0.75pt) of table cell spacing must survive DOCX read/reexport"
    );
}

fn spacing_fixture(element: Option<&str>) -> Vec<u8> {
    let mut document = Document::new();
    document.body.push(Arc::new(Block::Table(Table::new(1, 1, 72.0))));
    let mut parts = unzip(&wordcraft_docx::write(&document).unwrap());
    if let Some(element) = element {
        let xml = String::from_utf8(parts[MAIN].clone()).unwrap();
        assert_eq!(xml.matches("<w:tblPr>").count(), 1);
        parts.insert(MAIN.into(), xml.replacen("<w:tblPr>", &format!("<w:tblPr>{element}"), 1).into_bytes());
    }
    zip(&parts)
}

#[test]
fn table_cell_spacing_keeps_absence_distinct_from_explicit_and_word_zero_values() {
    for (element, points, file_value) in [
        (None, None, None),
        (Some(r#"<w:tblCellSpacing w:w="0" w:type="dxa"/>"#), Some(0.0), Some("0")),
        (Some(r#"<w:tblCellSpacing w:w="15" w:type="pct"/>"#), Some(0.0), Some("0")),
        (Some(r#"<w:tblCellSpacing w:w="15" w:type="auto"/>"#), Some(0.0), Some("0")),
        (Some(r#"<w:tblCellSpacing w:w="15" w:type="nil"/>"#), Some(0.0), Some("0")),
        (Some(r#"<w:tblCellSpacing w:w="15"/>"#), Some(0.75), Some("15")),
    ] {
        let document = wordcraft_docx::read(&spacing_fixture(element)).unwrap();
        let table = document.body.iter().find_map(|block| block.as_table()).unwrap();
        assert_eq!(table.props.cell_spacing, points, "file input: {element:?}");
        let exported = unzip(&wordcraft_docx::write(&document).unwrap());
        let spacing = table_cell_spacing(&exported[MAIN]);
        match file_value {
            None => assert!(spacing.is_empty(), "absent spacing must stay absent"),
            Some(value) => assert_eq!(spacing, vec![BTreeMap::from([("w:w".into(), value.into()), ("w:type".into(), "dxa".into())])]),
        }
    }
}

#[test]
fn table_cell_spacing_preserves_style_inheritance_and_explicit_zero_overrides() {
    use wordcraft_doc::styles::{Style, StyleKind, TableStyleParts};

    let mut document = Document::new();
    for (id, base, spacing) in
        [("SpacingBase", None, Some(0.75)), ("SpacingInherited", Some("SpacingBase"), None), ("SpacingZero", Some("SpacingInherited"), Some(0.0))]
    {
        document.styles.upsert(Style {
            id: id.into(),
            name: id.into(),
            kind: StyleKind::Table,
            based_on: base.map(str::to_string),
            table: Some(TableStyleParts { cell_spacing: spacing, ..Default::default() }),
            ..Default::default()
        });
    }
    for (style, own) in [("SpacingInherited", None), ("SpacingInherited", Some(0.0)), ("SpacingZero", None)] {
        let mut table = Table::new(1, 1, 72.0);
        table.props.style = Some(style.into());
        table.props.cell_spacing = own;
        document.body.push(Arc::new(Block::Table(table)));
    }
    let bytes = wordcraft_docx::write(&document).unwrap();
    let reopened = wordcraft_docx::read(&bytes).unwrap();
    assert_eq!(reopened.styles.table_style("SpacingBase").unwrap().parts.cell_spacing, Some(0.75));
    assert_eq!(reopened.styles.table_style("SpacingInherited").unwrap().parts.cell_spacing, Some(0.75));
    assert_eq!(reopened.styles.table_style("SpacingZero").unwrap().parts.cell_spacing, Some(0.0));
    assert_eq!(
        reopened.styles.get("SpacingInherited").unwrap().table.as_ref().and_then(|parts| parts.cell_spacing),
        None,
        "inheritance is not flattened into the child"
    );
    let own: Vec<_> = reopened.body.iter().filter_map(|block| block.as_table()).map(|table| table.props.cell_spacing).collect();
    assert_eq!(own, [None, Some(0.0), None], "table-local zero must not be turned into an inherited value");

    // The existing wholeTable path already represents table-wide style values.
    // Its explicit zero must likewise override the direct style's positive value.
    let mut parts = unzip(&bytes);
    let mut styles = String::from_utf8(parts["word/styles.xml"].clone()).unwrap();
    let start = styles.find(r#"w:styleId="SpacingBase""#).unwrap();
    let end = start + styles[start..].find("</w:style>").unwrap();
    styles.insert_str(end, r#"<w:tblStylePr w:type="wholeTable"><w:tblPr><w:tblCellSpacing w:w="0" w:type="dxa"/></w:tblPr></w:tblStylePr>"#);
    parts.insert("word/styles.xml".into(), styles.into_bytes());
    let whole = wordcraft_docx::read(&zip(&parts)).unwrap();
    assert_eq!(whole.styles.table_style("SpacingInherited").unwrap().parts.cell_spacing, Some(0.0));
    let again = wordcraft_docx::read(&wordcraft_docx::write(&whole).unwrap()).unwrap();
    assert_eq!(again.styles.table_style("SpacingInherited").unwrap().parts.cell_spacing, Some(0.0));
}
